/**
 * Mandelbulber v2 - Circle Inversion Transform (2D)
 * AUTO-GENERATED by Inverse Transform Tool
 */

#include "all_fractal_definitions.h"

class cFractalInvcircler150 : public cAbstractFractal
{
public:
	cFractalInvcircler150();
	void FormulaCode(CVector4 &z, const sFractal *fractal, sExtendedAux &aux) override;
};

cFractalInvcircler150::cFractalInvcircler150() : cAbstractFractal()
{
	nameInComboBox = "T>Inv Circle R1.5";
	internalName = "inv_circle_r150";
	internalID = fractal::inv_circle_r150;
	DEType = analyticDEType;
	DEFunctionType = linearDEFunction;
	cpixelAddition = cpixelDisabledByDefault;
	defaultBailout = 100.0;
	DEAnalyticFunction = analyticFunctionLinear;
	coloringFunction = coloringFunctionDefault;
}

void cFractalInvcircler150::FormulaCode(
	CVector4 &z, const sFractal *fractal, sExtendedAux &aux)
{
	// Circle inversion (2D in XY plane)
	CVector2<double> center = CVector2<double>(0, 0);
	double invRadius = 2.25;
	
	// Calculate 2D distance
	double rr = (z.x - center.x) * (z.x - center.x) +
	            (z.y - center.y) * (z.y - center.y);
	
	if (rr > 0.0001) // Guard
	{
		double factor = invRadius / rr;
		z.x = center.x + (z.x - center.x) * factor;
		z.y = center.y + (z.y - center.y) * factor;
		aux.DE *= factor;
	}
	
	// Scale
	z *= 1.0;
	aux.DE *= 1.0;
}
